const text={zh:{pilot:'百炼 API 已就绪',title:'告诉我你的业务，<em>开始推广。</em>',subtitle:'回答几个简单问题，获得一套由 AI 生成、可直接使用的营销内容方案。',business:'你的业务或品牌',businessPh:'例如：一家精品咖啡店',product:'这次想推广什么？',productPh:'例如：秋季限定燕麦拿铁',channel:'发布到哪里？',tone:'想要什么感觉？',generate:'生成我的营销方案 <i>→</i>',loading:'正在生成你的方案…',note:'你的内容只会发送给本站配置的 AI 服务，用于生成这次方案。',yourPlan:'你的内容方案',edit:'重新填写',headline:'推荐标题',caption:'发布文案',visual:'视觉方向',nextStep:'下一步',nextCopy:'用这份方案生成一张社媒海报',makePoster:'生成海报 <i>→</i>',copy:'复制文案',copied:'文案已复制',poster:'海报生成能力将在下一版接入！',failed:'暂时无法生成。请确认服务器已启动且百炼 API 已配置。'},en:{pilot:'BAILIAN API READY',title:'Tell us your business.<br><em>Start promoting.</em>',subtitle:'Answer a few simple questions and receive an AI-generated content plan you can use right away.',business:'Your business or brand',businessPh:'e.g. an independent coffee shop',product:'What are you promoting?',productPh:'e.g. a seasonal oat latte',channel:'Where will you publish?',tone:'What should it feel like?',generate:'Create my content plan <i>→</i>',loading:'Creating your plan…',note:'Your content is sent only to this site’s configured AI service to create this plan.',yourPlan:'YOUR CONTENT PLAN',edit:'Edit brief',headline:'RECOMMENDED HEADLINE',caption:'POST COPY',visual:'VISUAL DIRECTION',nextStep:'NEXT STEP',nextCopy:'Use this plan to create a social post',makePoster:'Create visual <i>→</i>',copy:'Copy text',copied:'Copy ready',poster:'Visual generation will be added in the next version!',failed:'Unable to create a plan. Check that the server is running and Bailing API is configured.'}};
const searchTask=new URLSearchParams(location.search).get('task');
if(searchTask){const context=document.querySelector('#taskContext'),productInput=document.querySelector('#product');context.hidden=false;context.textContent=`你的搜索目标：${searchTask}`;productInput.value=searchTask;}
let lang,timer;const form=document.querySelector('#brief'),result=document.querySelector('#result'),toast=document.querySelector('#toast'),submit=form.querySelector('[type=submit]');function words(){return text[lang]}function say(m){toast.textContent=m;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2600)}function setLang(next){lang=next;const t=words();document.documentElement.lang=next==='zh'?'zh-CN':'en';document.title=next==='zh'?'营销内容助手 · AI SuperMall':'Marketing Content Assistant · AI SuperMall';document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t[e.dataset.i18n]);document.querySelectorAll('[data-i18n-html]').forEach(e=>e.innerHTML=t[e.dataset.i18nHtml]);document.querySelectorAll('[data-i18n-placeholder]').forEach(e=>e.placeholder=t[e.dataset.i18nPlaceholder]);document.querySelector('#lang').textContent=next==='zh'?'EN':'中文';localStorage.setItem('supermall-studio-language',next)}
const china=['Asia/Shanghai','Asia/Urumqi','Asia/Chongqing','Asia/Harbin'].includes(Intl.DateTimeFormat().resolvedOptions().timeZone);setLang(localStorage.getItem('supermall-studio-language')||(china?'zh':'en'));document.querySelector('#lang').onclick=()=>setLang(lang==='zh'?'en':'zh');
form.onsubmit=async e=>{e.preventDefault();const data={business:document.querySelector('#business').value,product:document.querySelector('#product').value,channel:document.querySelector('#channel').value,tone:document.querySelector('#tone').value,language:lang};const original=submit.innerHTML;submit.disabled=true;submit.textContent=words().loading;try{const response=await fetch('/api/marketing-plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const plan=await response.json();if(!response.ok)throw new Error(plan.error);document.querySelector('#resultTitle').textContent=plan.title;document.querySelector('#headline').textContent=plan.headline;document.querySelector('#caption').textContent=plan.caption;document.querySelector('#visual').textContent=plan.visual;form.hidden=true;result.hidden=false;result.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){say(error.message||words().failed)}finally{submit.disabled=false;submit.innerHTML=original}};
document.querySelector('#newBrief').onclick=()=>{result.hidden=true;form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'})};document.querySelector('.copy').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#caption').textContent);say(words().copied)}catch{say(document.querySelector('#caption').textContent)}};document.querySelector('#poster').onclick=()=>say(words().poster);
const modal=document.querySelector('#memberModal'),emailInput=document.querySelector('#memberEmail');
function storeProject(){const projects=JSON.parse(localStorage.getItem('supermall-projects')||'[]');projects.unshift({savedAt:new Date().toISOString(),business:document.querySelector('#business').value,product:document.querySelector('#product').value,title:document.querySelector('#resultTitle').textContent,headline:document.querySelector('#headline').textContent,caption:document.querySelector('#caption').textContent,visual:document.querySelector('#visual').textContent});localStorage.setItem('supermall-projects',JSON.stringify(projects));say('已保存到我的项目');}
document.querySelector('#saveProject').onclick=()=>{const email=localStorage.getItem('supermall-member-email');if(email){storeProject();return}modal.hidden=false;emailInput.focus()};
document.querySelector('#closeModal').onclick=()=>modal.hidden=true;
document.querySelector('#confirmSave').onclick=()=>{const email=emailInput.value.trim();if(!/^\S+@\S+\.\S+$/.test(email)){say('请输入正确的邮箱地址');return}localStorage.setItem('supermall-member-email',email);modal.hidden=true;storeProject();};
